<script setup>
import { computed, ref } from 'vue'
import { identityFromChart, identity60, identityElements } from '../services/identity60.js'
import { stemThai, elementThaiLabel } from '../services/bazi.js'
import Identity60Art from './Identity60Art.vue'
import Identity60 from './Identity60.vue'
const props=defineProps({chart:Object,assessment:Object,input:Object,name:String,plan:{type:String,default:'Free'}})
const emit=defineEmits(['edit','packages'])
const tab=ref('personality'),catalog=ref(false)
const own=computed(()=>identityFromChart(props.chart))
const names=['ตัวตนของคุณ','จุดแข็ง','สิ่งที่ควรระวัง','การงาน','การเงิน','ความรักและความสัมพันธ์','ลองทำวันนี้']
const zodiac=p=>['ชวด','ฉลู','ขาล','เถาะ','มะโรง','มะเส็ง','มะเมีย','มะแม','วอก','ระกา','จอ','กุน']['子丑寅卯辰巳午未申酉戌亥'.indexOf(p?.branch)]||'—'
const birthLabel=computed(()=>{const v=props.input?.birthDate;if(!v)return '';const parts=v.includes('/')?v.split('/').reverse():v.split('-');return new Intl.DateTimeFormat('th-TH',{dateStyle:'long',timeZone:'UTC'}).format(new Date(Date.UTC(+parts[0],+parts[1]-1,+parts[2])))})
const pair=computed(()=>own.value?identity60.find(item=>['甲己','乙庚','丙辛','丁壬','戊癸'].some(p=>p.includes(own.value.id[0])&&p.includes(item.id[0])&&own.value.id[0]!==item.id[0])&&['子丑','寅亥','卯戌','辰酉','巳申','午未'].some(p=>p.includes(own.value.id[1])&&p.includes(item.id[1])&&own.value.id[1]!==item.id[1])):null)
const strengthLabels={very_weak:'อ่อนมาก',weak:'อ่อน',balanced:'สมดุล',strong:'แข็ง',very_strong:'แข็งมาก'}
const elements=computed(()=>{const totals=props.assessment?.diagnostics?.elementPresence||{};const sum=Object.values(totals).reduce((a,b)=>a+b,0);return identityElements.map((e,i)=>({...e,x:160+103*Math.sin(i*2*Math.PI/5),y:150-103*Math.cos(i*2*Math.PI/5),char:'木火土金水'[i],percent:sum?Math.round((totals[e.key]||0)/sum*100):0,helpful:['primary','supportive'].includes(props.assessment?.elementAssessments?.[e.key]?.status)}))})
const relations=computed(()=>{const i=identityElements.findIndex(e=>e.key===props.chart?.dayMaster?.element);return i<0?[]:[[(i+4)%5,'ส่งเสริมคุณ'],[(i+1)%5,'คุณส่งเสริม'],[(i+2)%5,'คุณควบคุม'],[(i+3)%5,'ควบคุมคุณ']].map(([n,text])=>({...identityElements[n],text}))})
const pillars=computed(()=>['hour','day','month','year'].map((key,i)=>({key,label:['ยาม','วัน','เดือน','ปี'][i],value:key==='hour'&&!props.input?.birthTime?null:props.chart?.pillars?.[key]})))
</script>
<template>
<section class="my-chart">
<header class="my-heading"><small>รู้จักตัวเองผ่านปาจื้อ</small><h2>ดวงของ{{ name || 'ฉัน' }}</h2><div>เกิด {{ birthLabel }} <button @click="emit('edit')">แก้ไขข้อมูลเกิด</button></div></header>
<div class="my-body">
<div class="my-tabs" role="tablist" aria-label="หมวดดวงของฉัน"><button v-for="item in [{id:'personality',label:'บุคลิก'},{id:'elements',label:'ธาตุประจำตัว'}]" :key="item.id" role="tab" :aria-selected="tab===item.id" @click="tab=item.id;catalog=false">{{ item.label }}</button></div>
<template v-if="tab==='personality'">
<template v-if="own">
<article class="my-card persona"><Identity60Art :identity="own"/><small>บุคลิกตามเสาวัน · แบบที่ {{ own.number }} จาก 60</small><h2>{{ own.title }}</h2><strong>{{ own.subtitle }}</strong><p>{{ own.summary }}</p><div class="my-chips"><span>{{ stemThai(chart.pillars.day) }}</span><span>เสาวัน · {{ zodiac(chart.pillars.day) }}</span></div></article>
<article class="my-card readings"><details v-for="(part,index) in own.sections" :key="part.title" :open="index===0"><summary>{{ names[index] }}</summary><p>{{ part.text }}</p></details></article>
<details v-if="pair" class="my-card pair-card"><summary><small>เสาวันคู่ประสาน · คู่บุญ</small><strong>{{ pair.title }}</strong><span>ก้านวันและกิ่งวันประสานกัน · กดอ่านบุคลิก</span></summary><p>{{ pair.summary }}</p><p>{{ pair.sections[5].text }}</p></details>
</template>
<p v-else class="my-card">เพิ่มข้อมูลเกิดเพื่ออ่านตัวตนของคุณ <button @click="emit('edit')">ไปข้อมูลเกิด</button></p>
<button class="catalog-button" :aria-expanded="catalog" @click="catalog=!catalog">{{ catalog?'ซ่อนบุคลิกทั้ง 60 แบบ':'ดูบุคลิกทั้ง 60 แบบ' }}</button><Identity60 v-if="catalog" :chart="chart"/>
</template>
<template v-else-if="chart && assessment">
<article class="my-card"><svg class="element-wheel" viewBox="0 0 320 285" role="img" aria-label="วงจรห้าธาตุ ลูกศรทึบส่งเสริม ลูกศรประควบคุม"><defs><marker id="my-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="#c2b5ad"/></marker></defs><g v-for="(e,i) in elements" :key="e.key"><line :x1="e.x" :y1="e.y" :x2="e.x+(elements[(i+1)%5].x-e.x)*.72" :y2="e.y+(elements[(i+1)%5].y-e.y)*.72" stroke="#c2b5ad" stroke-width="1.5" marker-end="url(#my-arrow)"/><line :x1="e.x" :y1="e.y" :x2="e.x+(elements[(i+2)%5].x-e.x)*.83" :y2="e.y+(elements[(i+2)%5].y-e.y)*.83" stroke="#e6c8c4" stroke-dasharray="4 5" marker-end="url(#my-arrow)"/></g><g v-for="e in elements" :key="e.key"><circle v-if="e.key===chart.dayMaster.element" :cx="e.x" :cy="e.y" r="36" fill="none" stroke="#b68d40" stroke-width="3"/><circle :cx="e.x" :cy="e.y" r="30" :fill="e.color"/><text :x="e.x" :y="e.y+2" text-anchor="middle" fill="white" font-size="26">{{ e.char }}</text><text :x="e.x" :y="e.y+20" text-anchor="middle" fill="white" font-size="11">{{ e.label }}</text></g></svg><div class="relation-grid"><span v-for="e in relations" :key="e.key"><i :style="{background:e.color}"/>{{ e.label }} · {{ e.text }}</span></div><p class="quiet">วงแหวนทองคือธาตุประจำตัวของคุณ</p></article>
<article class="my-card summary-list"><div><span>ธาตุประจำตัว</span><b>{{ stemThai(chart.pillars.day) }}</b></div><div><span>พลังธาตุ</span><b>{{ strengthLabels[assessment.strengthLevel] || assessment.strengthLevel }}</b></div><div><span>ธาตุที่ช่วยสมดุล</span><b>{{ elements.filter(e=>e.helpful).map(e=>e.label).join(' · ') || 'ยังไม่ชัดเจน' }}</b></div><div><span>ปีนักษัตรเกิด</span><b>{{ zodiac(chart.pillars.year) }}</b></div><div><span>บุคลิกเสาวัน</span><b>{{ own?.title }}</b></div></article>
<article class="my-card"><h3>ตารางธาตุสี่เสา</h3><div class="four-pillars"><div v-for="p in pillars" :key="p.key" :class="{'your-pillar':p.key==='day'}"><h4>{{ p.label }}</h4><template v-if="p.value"><strong>{{ p.value.stem }}</strong><small>{{ stemThai(p.value) }}</small><strong>{{ p.value.branch }}</strong><small>{{ zodiac(p.value) }}</small><div class="hidden-stems"><span v-for="h in p.value.hiddenStems" :key="h.stem">{{ elementThaiLabel(h.element) }}{{ h.polarity==='yin'?'หยิน':'หยาง' }}</span></div></template><small v-else>ไม่ทราบเวลาเกิด</small></div></div><p class="quiet">ก้านฟ้าของเสาวันคือตัวคุณ · แถวล่างคือธาตุแฝงในกิ่งดิน</p></article>
<article class="my-card"><h3>สมดุลธาตุในดวง</h3><div v-for="e in elements" :key="e.key" class="balance-row"><span>{{ e.label }}</span><div class="balance-track"><i :style="{width:e.percent+'%',background:e.color}"/></div><b>{{ e.percent }}%</b><small>{{ e.helpful?'ช่วยสมดุล':'' }}</small></div><p class="quiet">สัดส่วนจากน้ำหนักธาตุในสูตรของเรา รวมก้านฟ้าและธาตุแฝง ไม่ใช่เปอร์เซ็นต์ความแม่นยำ</p></article>
</template>
<p v-else class="my-card">เพิ่มเวลาเกิดและเพศเพื่ออ่านธาตุครบสี่เสา <button @click="emit('edit')">ไปข้อมูลเกิด</button></p>
<article class="my-card"><h3>สมาชิก</h3><div class="membership-line"><b>{{ plan }}</b><button class="catalog-button" @click="emit('packages')">ดูแพ็กเกจ / จัดการสมาชิก</button></div></article>
<article class="my-card settings"><h3>การตั้งค่า</h3><button @click="emit('edit')">แก้ไขข้อมูลวันเกิด <span>›</span></button><a href="mailto:support.geniuspicture@gmail.com">ติดต่อทีมงาน <span>›</span></a><a href="/privacy.html" target="_blank" rel="noopener">ความเป็นส่วนตัว / การขอลบข้อมูล <span>›</span></a></article>
</div></section>
</template>
<style scoped>
.my-chart{max-width:860px;margin:auto;min-width:0;color:#51413c}.my-heading{padding:24px;color:#fff6ed;background:linear-gradient(130deg,#772839,#b87673)}.my-heading h2{font-size:1.65rem;margin:8px 0}.my-heading small{opacity:.7}.my-heading div{font-size:.8rem;display:flex;gap:10px;flex-wrap:wrap;align-items:center}.my-heading button{border:1px solid #fff5;border-radius:20px;color:inherit;background:#fff1;padding:5px 12px;font:inherit}.my-body{padding:18px;background:#faf6f2}.my-tabs{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:18px}.my-tabs button,.catalog-button{padding:12px;border:1px solid #e7dcd4;background:#fffdfa;border-radius:12px;color:#7c5b55;font:inherit;cursor:pointer}.my-tabs button[aria-selected=true]{background:#792c40;color:white;border-color:#792c40}.my-card{padding:20px;border:1px solid #ebe1d9;background:#fffdfa;border-radius:20px;margin-bottom:16px;min-width:0}.my-card h3{font-size:1rem;margin:0 0 18px}.persona{text-align:center}.persona :deep(.identity60-art){width:180px;max-width:70%;margin:0 auto 18px;display:block}.persona>small{display:block;color:#a08778}.persona h2{font-size:1.6rem;color:#772839;margin:10px 0}.persona strong{font-size:.9rem}.my-card p{font-size:.85rem;line-height:1.85}.my-chips{display:flex;gap:8px;justify-content:center;flex-wrap:wrap}.my-chips span{padding:5px 12px;border-radius:20px;background:#f3e6df;font-size:.75rem}.readings details{border-bottom:1px solid #eee4dd;padding:14px 0}.readings details:first-child{padding-top:0}.readings details:last-child{border:0}.readings summary{cursor:pointer;font-weight:600;font-size:.9rem}.pair-card{background:#f5e9e4}.pair-card summary{display:grid;gap:7px;cursor:pointer}.pair-card small,.pair-card span{font-size:.75rem;color:#987365}.catalog-button{width:100%;margin:0 0 18px}.element-wheel{width:100%;max-width:340px;display:block;margin:auto}.relation-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;font-size:.75rem}.relation-grid i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.quiet{font-size:.7rem!important;color:#9c877b;line-height:1.7}.summary-list>div{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid #efe5dd;font-size:.8rem}.summary-list>div:last-child{border:0}.summary-list span{color:#9c877b;flex-shrink:0}.summary-list b{text-align:right}.four-pillars{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px;text-align:center}.four-pillars>div{border-radius:12px;background:#f8f2ec;padding:10px 3px}.four-pillars .your-pillar{background:#f3e3e5}.four-pillars h4{font-size:.8rem;margin:0 0 12px}.four-pillars strong{display:block;font-size:1.7rem;color:#853549;margin:7px 0}.four-pillars small{display:block;font-size:.65rem}.hidden-stems{border-top:1px solid #e6d9d0;margin-top:12px;padding-top:10px;min-height:64px}.hidden-stems span{display:block;font-size:.6rem;line-height:1.7}.balance-row{display:grid;grid-template-columns:24px 1fr 35px 54px;gap:8px;align-items:center;font-size:.75rem;margin:14px 0}.balance-row small{font-size:.6rem;color:#987b57}.balance-track{height:9px;background:#eee7df;border-radius:20px;overflow:hidden}.balance-track i{display:block;height:100%;border-radius:20px}.membership-line{display:flex;justify-content:space-between;align-items:center}.settings button,.settings a{display:flex;justify-content:space-between;gap:12px;width:100%;padding:14px 0;border:0;border-bottom:1px solid #eee4dd;background:none;text-decoration:none;color:inherit;font:inherit;font-size:.85rem;cursor:pointer}.settings span{color:#ae8b7a}.my-chart button:focus-visible,.my-chart summary:focus-visible{outline:3px solid #b99458;outline-offset:3px}@media(max-width:360px){.my-body{padding:12px}.my-card{padding:16px 12px}.relation-grid{gap:8px;font-size:.68rem}}
</style>
